insert into public.regions ("id","name","description","rarity","sort_order","image_path","requires_map_fragment") values
('mechsanctum','기계신의 성소','수많은 톱니가 맞물려 생명을 이루는 바다. 황동 성소의 청록빛 동력을 따라 기계신과 수호자들을 만나 보세요.','epic',15,'/regions/mechsanctum/scenery-v1.png',true)
insert into public.fishing_map_blueprints ("region_id","piece_count","thumbnail_path","enabled","rarity") values
('mechsanctum',6,'/regions/mechsanctum/map-v1.png',true,'rare')
insert into public.collectible_species ("id","kind","name","description","swim_y_min","swim_y_max","speed","size","rarity","thumbnail_path","sell_price","sprite_sheet_path","native_region_id","movement_type","flip_with_direction","travel_direction") values
('mechsanctum-aion','fish','영겁의 고래 아이온','열린 옆구리 안의 황금 톱니가 느리게 회전하며 묵직한 종소리를 내는 기계 고래예요.','0.18','0.78','0.024',115,'epic','fish/epic/mechsanctum-aion_v1_thumbnail.png',920,'fish/epic/mechsanctum-aion_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-armored-horseshoe','fish','톱니갑옷 투구게','겹겹의 톱니 갑옷으로 몸을 감싼 투구게예요. 긴 꼬리로 모래를 짚어요.','0.85','0.95','0.012',70,'rare','fish/rare/mechsanctum-armored-horseshoe_v1_thumbnail.png',250,'fish/rare/mechsanctum-armored-horseshoe_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-automakion','fish','천륜의 심판자, 오토마키온','중심의 세로 눈을 여러 겹의 톱니 고리가 감싼 기계신이에요. 눈을 뜨면 봉인된 문 같은 몸이 펼쳐져요.','0.18','0.78','0.010',185,'mythic','fish/mythic/mechsanctum-automakion_v1_thumbnail.png',4000,'fish/mythic/mechsanctum-automakion_swim8_v1_sprite.png','mechsanctum','pulse',true,'both'),
('mechsanctum-backward-fish','trash','거꾸로 조립된 물고기','지느러미와 꼬리가 엉뚱한 곳에 달려 움직이지 못하는 기계 물고기예요.','0.82','0.92','0.001',40,'rare','trash/rare/mechsanctum-backward-fish_v1_thumbnail.png',50,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-bearing-urchin','fish','베어링성게','매끈한 베어링 구슬 사이로 짧은 금속 가시를 세운 성게예요.','0.85','0.95','0.012',54,'common','fish/normal/mechsanctum-bearing-urchin_v1_thumbnail.png',52,'fish/normal/mechsanctum-bearing-urchin_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-brass-carp','fish','황동붕어','둥근 황동 톱니가 비늘처럼 겹쳐진 통통한 붕어예요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-brass-carp_v1_thumbnail.png',64,'fish/normal/mechsanctum-brass-carp_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-brass-column','decoration','황동 톱니 기둥','작은 황동 톱니를 층층이 쌓아 올린 기둥이에요.',null,null,'0',54,'common','decorations/normal/mechsanctum-brass-column_v1_thumbnail.png',38,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-broken-prayer-circuit','trash','끊어진 기도회로','기도를 전달하던 구리 회로가 중간에서 끊어져 있어요.','0.82','0.92','0.001',32,'common','trash/normal/mechsanctum-broken-prayer-circuit_v1_thumbnail.png',15,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-clockwork-anchovy','fish','태엽멸치','은빛 몸통 안에서 황동 톱니와 태엽이 맞물리고, 등 위의 작은 열쇠로 동력을 채우는 멸치예요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-clockwork-anchovy_v1_thumbnail.png',58,'fish/normal/mechsanctum-clockwork-anchovy_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-copper-coral','decoration','구리선 산호','가느다란 구리선이 가지를 뻗어 산호처럼 자란 장식이에요.',null,null,'0',54,'common','decorations/normal/mechsanctum-copper-coral_v1_thumbnail.png',30,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-copper-pipes','decoration','구리 배관 묶음','성소의 동력수를 나르던 구리 배관을 가지런히 묶었어요.',null,null,'0',54,'common','decorations/normal/mechsanctum-copper-pipes_v1_thumbnail.png',32,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-counter-jellyfish','fish','역회전 해파리','우산을 이루는 두 겹의 톱니 고리가 서로 반대 방향으로 회전해요.','0.18','0.78','0.010',70,'rare','fish/rare/mechsanctum-counter-jellyfish_v1_thumbnail.png',260,'fish/rare/mechsanctum-counter-jellyfish_v1_sprite.png','mechsanctum','pulse',true,'both'),
('mechsanctum-creator-blueprint','decoration','창조주의 설계도','성소의 설계 일부가 남은 도면이에요. 작은 황동 틀 안에 펼쳐져 있어요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-creator-blueprint_v1_thumbnail.png',90,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-crown-octopus','fish','금관톱니 문어','머리의 왕관형 기어가 돌아가면 여덟 팔의 작은 톱니가 함께 움직여요.','0.85','0.95','0.012',70,'rare','fish/rare/mechsanctum-crown-octopus_v1_thumbnail.png',295,'fish/rare/mechsanctum-crown-octopus_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-deus-machina','fish','태초의 설계자, 데우스 마키나','여섯 기계 팔과 하나의 청록빛 눈을 가진 심해 신격이에요. 자신의 몸과 성소를 끊임없이 조립해요.','0.18','0.78','0.014',185,'mythic','fish/mythic/mechsanctum-deus-machina_v1_thumbnail.png',3800,'fish/mythic/mechsanctum-deus-machina_swim8_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-deus-zero','decoration','심장을 잃은 신, 데우스 제로','텅 빈 가슴으로 작은 물고기가 드나드는 기계 거인이에요. 머리 위에는 부서진 톱니 후광이 떠 있어요.',null,null,'0',175,'mythic','decorations/mythic/mechsanctum-deus-zero_v1_thumbnail.png',2700,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-empty-crown','trash','기계신의 빈 왕관','주인을 잃은 작은 왕관이에요. 가운데의 동력석 자리만 비어 있어요.','0.82','0.92','0.001',40,'rare','trash/rare/mechsanctum-empty-crown_v1_thumbnail.png',60,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-eternal-pendulum','decoration','영겁의 진자','황동 틀 안에서 긴 시계추가 고요히 시간을 세는 장식이에요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-eternal-pendulum_v1_thumbnail.png',100,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-filter-residue','trash','성수 필터 찌꺼기','성수를 걸러낸 낡은 필터에 청록빛 찌꺼기가 남아 있어요.','0.82','0.92','0.001',40,'rare','trash/rare/mechsanctum-filter-residue_v1_thumbnail.png',40,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-gear-flounder','fish','기어가자미','납작한 원형 톱니 몸체 위에 두 눈이 올라온 가자미예요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-gear-flounder_v1_thumbnail.png',62,'fish/normal/mechsanctum-gear-flounder_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-gear-starfish','fish','톱니불가사리','다섯 개의 작은 톱니가 중앙 기어와 맞물려 움직이는 불가사리예요.','0.85','0.95','0.012',54,'common','fish/normal/mechsanctum-gear-starfish_v1_thumbnail.png',55,'fish/normal/mechsanctum-gear-starfish_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-guardian-throne','decoration','잠든 수호자의 석좌','잠든 수호자를 위해 비워둔 석좌예요. 등받이의 톱니 문양이 닳아 있어요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-guardian-throne_v1_thumbnail.png',110,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-helix','fish','역행의 나선 헬릭스','거대한 나선 껍데기의 톱니를 거꾸로 돌려 주변 해류를 끌어당기는 앵무조개예요.','0.18','0.78','0.024',115,'epic','fish/epic/mechsanctum-helix_v1_thumbnail.png',830,'fish/epic/mechsanctum-helix_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-hinge-scallop','fish','경첩가리비','황동 경첩으로 연결된 두 껍데기를 열고 닫는 가리비예요.','0.85','0.95','0.012',54,'common','fish/normal/mechsanctum-hinge-scallop_v1_thumbnail.png',60,'fish/normal/mechsanctum-hinge-scallop_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-layered-nautilus','fish','겹톱니 앵무조개','껍데기 안에 여러 겹의 황동 기어가 겹쳐 돌아가는 앵무조개예요.','0.18','0.78','0.024',70,'rare','fish/rare/mechsanctum-layered-nautilus_v1_thumbnail.png',265,'fish/rare/mechsanctum-layered-nautilus_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-meshing-crab','fish','맞물림게','양쪽 집게의 톱니를 맞물려 먹이를 잘게 부수는 게예요.','0.85','0.95','0.012',54,'common','fish/normal/mechsanctum-meshing-crab_v1_thumbnail.png',66,'fish/normal/mechsanctum-meshing-crab_v1_sprite.png','mechsanctum','crawl',true,'both'),
('mechsanctum-nema','fish','백팔륜의 사제 네마','빛나는 중심 기어를 품은 문어 사제예요. 여덟 팔의 톱니를 맞물려 제단을 가동해요.','0.18','0.78','0.024',115,'epic','fish/epic/mechsanctum-nema_v1_thumbnail.png',810,'fish/epic/mechsanctum-nema_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-orbis','fish','천륜의 수호자 오르비스','수백 개의 톱니로 짜인 날개와 거대한 기어 고리를 두른 성소의 수호 가오리예요.','0.18','0.78','0.024',115,'epic','fish/epic/mechsanctum-orbis_v1_thumbnail.png',850,'fish/epic/mechsanctum-orbis_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-ouros','fish','성소를 감싼 우로스','자기 꼬리를 물고 거대한 원을 이루어 성소의 동력을 순환시키는 고리 기어 바다뱀이에요.','0.18','0.78','0.024',115,'epic','fish/epic/mechsanctum-ouros_v1_thumbnail.png',890,'fish/epic/mechsanctum-ouros_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-pendulum-ray','fish','시계추 가오리','톱니로 짜인 양 날개 아래로 긴 시계추 꼬리가 흔들리는 가오리예요.','0.18','0.78','0.024',70,'rare','fish/rare/mechsanctum-pendulum-ray_v1_thumbnail.png',285,'fish/rare/mechsanctum-pendulum-ray_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-planetary-puffer','fish','유성기어 복어','중앙 톱니 주위를 작은 톱니들이 공전해요. 부풀면 기어가 바깥으로 펼쳐져요.','0.18','0.78','0.024',70,'rare','fish/rare/mechsanctum-planetary-puffer_v1_thumbnail.png',290,'fish/rare/mechsanctum-planetary-puffer_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-plate-filefish','fish','철판쥐치','얇은 철판을 비늘처럼 이어 붙인 쥐치예요. 지느러미 끝에 작은 볼트가 달렸어요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-plate-filefish_v1_thumbnail.png',69,'fish/normal/mechsanctum-plate-filefish_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-prayer-lamp','decoration','기계신의 기도등','청록빛 동력이 은은하게 비치는 작은 기도등이에요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-prayer-lamp_v1_thumbnail.png',95,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-praying-automaton','decoration','기도하는 자동인형','두 손을 모으고 고개를 숙인 자동인형이에요. 가슴의 톱니가 조용히 돌아가요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-praying-automaton_v1_thumbnail.png',105,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-pressure-gauge','decoration','황동 압력계','동력수의 압력을 재던 둥근 황동 계기예요.',null,null,'0',54,'common','decorations/normal/mechsanctum-pressure-gauge_v1_thumbnail.png',34,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-priest-screw','trash','기계 사제의 나사','기계 사제가 정비를 마친 뒤 남긴 작은 나사예요.','0.82','0.92','0.001',32,'common','trash/normal/mechsanctum-priest-screw_v1_thumbnail.png',12,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-pulley-halfbeak','fish','도르래학꽁치','긴 아래턱 끝의 도르래로 얇은 구리선을 감아 먹이를 끌어당겨요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-pulley-halfbeak_v1_thumbnail.png',70,'fish/normal/mechsanctum-pulley-halfbeak_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-rejected-prayer','trash','반려된 기도문','접수되지 못한 기도문이에요. 가장자리에 작은 기름 자국이 남았어요.','0.82','0.92','0.001',32,'common','trash/normal/mechsanctum-rejected-prayer_v1_thumbnail.png',17,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-repairing-tree','decoration','자가수복 톱니나무','떨어진 톱니를 가지에 다시 끼우며 자라는 작은 기계 나무예요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-repairing-tree_v1_thumbnail.png',115,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-ring-eel','fish','환형톱니 장어','고리 모양 기어들이 길게 이어진 장어예요. 마디를 비틀어 방향을 바꿔요.','0.18','0.78','0.024',70,'rare','fish/rare/mechsanctum-ring-eel_v1_thumbnail.png',255,'fish/rare/mechsanctum-ring-eel_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-rusted-joint','trash','녹슨 관절 부품','관절을 움직이던 부품이에요. 녹이 슬어 더는 접히지 않아요.','0.82','0.92','0.001',32,'common','trash/normal/mechsanctum-rusted-joint_v1_thumbnail.png',17,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-rusty-sardine','fish','녹슨정어리','녹슨 톱니 비늘을 가진 정어리예요. 헤엄칠 때마다 작게 삐걱거려요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-rusty-sardine_v1_thumbnail.png',46,'fish/normal/mechsanctum-rusty-sardine_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-screw-medaka','fish','나사송사리','작은 나사 마디를 이어 만든 몸으로 물살 사이를 빠르게 누비는 송사리예요.','0.18','0.78','0.024',54,'common','fish/normal/mechsanctum-screw-medaka_v1_thumbnail.png',50,'fish/normal/mechsanctum-screw-medaka_v1_sprite.png','mechsanctum','swim',true,'both'),
('mechsanctum-silver-guardian','decoration','백은 수호상','성소의 입구를 지키던 수호자를 은백색으로 빚은 작은 상이에요.',null,null,'0',75,'rare','decorations/rare/mechsanctum-silver-guardian_v1_thumbnail.png',100,null,'mechsanctum','fixed',false,'both'),
('mechsanctum-silver-seahorse','fish','백은톱니 해마','은백색의 정교한 기어로 이루어진 해마예요. 꼬리가 말리면 톱니가 차례로 맞물려요.','0.18','0.78','0.024',70,'rare','fish/rare/mechsanctum-silver-seahorse_v1_thumbnail.png',280,'fish/rare/mechsanctum-silver-seahorse_v1_sprite.png','mechsanctum','swim',true,'both'),
